import Sns from "./Sns";
import { useTranslation } from 'react-i18next';

function Main(){
	const { t } = useTranslation();

	return(
		<div className="main">
			<div className="text_box">
				<strong>01</strong>
				<span>Gowoonsesang Cosmetics</span>
				<h3>건강한 피부로 <br/> 누구나 고운 세상</h3>
				<p>우리는 피부과학으로 고운세상을 만들고 있습니다.</p>
			</div>
			<div className="pc"><img src={`/images/${t("main.pc")}`} alt={t("main.pc").split(".")[0]}/></div>
			<div className="mo"><img src={`/images/${t("main.mo")}`} alt={t("main.mo").split(".")[0]}/></div>
			<div className="inb">
				<Sns/>
				<a href=""><img src={`/images/${data.main.go}`} alt={data.main.go.split(".")[0]}/></a>
			</div>
		</div>
	)
}

export default Main;
